BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
SELECT has_function('public','save_supplier_design_instruction',ARRAY['uuid','uuid','text','text','text','jsonb','boolean'],'Versioned supplier paragraph writer exists');
INSERT INTO auth.users(id,email) SELECT ('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'instructions-'||n||'@local.test' FROM generate_series(1,3)n;
INSERT INTO public.users(id,auth_id,username,role,name) SELECT ('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'instruction_test_'||n,(ARRAY['admin','designer','designer'])[n],'Instruction test '||n FROM generate_series(1,3)n;
INSERT INTO public.suppliers(id,name,phone) VALUES('ab100000-0000-4000-8000-000000000010','QA Secret Supplier','01000000001');
INSERT INTO public.doctors(id,name,phone,address,doctor_code,representative_name) VALUES('ab100000-0000-4000-8000-000000000011','Instruction doctor','01000000000','QA','INS-QA','QA');
INSERT INTO public.orders(id,case_id,doctor_id,patient_name,items,total_price,cost,shade,production_status,delivery_date,workflow_type,designer_id,supplier_id)
VALUES('ab100000-0000-4000-8000-000000000012','INS-CASE','ab100000-0000-4000-8000-000000000011','QA','[]',100,10,'A1','designing',current_date,'split','ab100000-0000-4000-8000-000000000002','ab100000-0000-4000-8000-000000000010');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
SELECT throws_ok($$SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000020','Safe paragraph','Private source','approved','[]',false)$$,'22023','Privacy review required','Publishing requires explicit privacy review');
SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000020','Safe paragraph','Private source QA Secret Supplier','approved','[]',true);
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000002',true);
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012',NULL)->>'paragraph','Safe paragraph','Assigned designer reads technical paragraph');
SELECT ok(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012',NULL)::text NOT LIKE '%Secret Supplier%','Supplier identity and private source excluded from projection');
SELECT throws_ok($$SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010',gen_random_uuid(),'Changed','source','approved','[]',true)$$,'42501','Admin role required','Designer cannot maintain supplier settings');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.supplier_design_instructions),0::bigint,'Designer cannot read raw source versions');
RESET ROLE;
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-qc-files','ab100000-0000-4000-8000-000000000012/ab100000-0000-4000-8000-000000000030/execution.zip','{"eTag":"immutable-instruction-test","size":100,"mimetype":"application/zip"}');
SELECT public.submit_design_revision('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030','https://example.test/files','no standalone preview');
SELECT is((SELECT supplier_instruction_id FROM public.design_revisions WHERE id='ab100000-0000-4000-8000-000000000030'),'ab100000-0000-4000-8000-000000000020'::uuid,'Submission snapshots supplier paragraph version');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000030',gen_random_uuid(),'approved','');
SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000021','New paragraph','New private source','experimental','[]',true);
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030')->>'paragraph','Safe paragraph','Prior submission keeps technical snapshot');
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012',NULL)->>'paragraph','New paragraph','Current technical version available for next submission');
SELECT ok(public.design_qc_gate_passes('ab100000-0000-4000-8000-000000000030'),'Supplier paragraph change does not invalidate file approval');
SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000022','Stopped paragraph','Private reason','stopped','[]',true);
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012',NULL)->>'status','stopped','Stopped technical settings are explicit');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012',NULL)$$,'42501','Design access denied','Unassigned designer cannot read settings');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
SELECT throws_ok($$SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010',gen_random_uuid(),'QA Secret Supplier settings','','approved','[]',true)$$,'22023','Remove supplier identity from shared paragraph','Known supplier name cannot be published');
SELECT throws_ok($$SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010',gen_random_uuid(),'Call 01000000001','','approved','[]',true)$$,'22023','Remove supplier identity from shared paragraph','Known supplier phone cannot be published');
SELECT is(jsonb_array_length(public.get_supplier_design_instructions('ab100000-0000-4000-8000-000000000010')),3,'Admin sees append-only version history');
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-instructions','ab100000-0000-4000-8000-000000000010/ab100000-0000-4000-8000-000000000023/ab100000-0000-4000-8000-000000000024.pdf','{"size":100,"mimetype":"application/pdf"}');
SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000023','Attachment version','Private source','approved','["ab100000-0000-4000-8000-000000000010/ab100000-0000-4000-8000-000000000023/ab100000-0000-4000-8000-000000000024.pdf"]',true);
SELECT is(public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000023','Attachment version','Private source','approved','["ab100000-0000-4000-8000-000000000010/ab100000-0000-4000-8000-000000000023/ab100000-0000-4000-8000-000000000024.pdf"]',true),'ab100000-0000-4000-8000-000000000023'::uuid,'Identical retry preserves immutable version');
SELECT throws_ok($$SELECT public.save_supplier_design_instruction('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000023','Mutated','','approved','[]',true)$$,'P0001','Instruction retry mismatch','Retry cannot replace saved content');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$INSERT INTO storage.objects(bucket_id,name) VALUES('design-instructions','reveals-supplier.pdf')$$,'42501',NULL,'Even admin cannot upload identity-bearing file names');
WITH changed AS(UPDATE storage.objects SET metadata='{}' WHERE bucket_id='design-instructions' RETURNING id) SELECT is((SELECT count(*) FROM changed),0::bigint,'Published attachments cannot be overwritten');
-- Match the Storage service's delete setting, so RLS itself must deny removal.
SET LOCAL storage.allow_delete_query='true';
WITH removed AS(DELETE FROM storage.objects WHERE bucket_id='design-instructions' RETURNING id) SELECT is((SELECT count(*) FROM removed),0::bigint,'Published attachments cannot be deleted');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='design-instructions'),1::bigint,'Assigned designer reads current technical attachment');
SELECT is(public.get_supplier_design_instructions('ab100000-0000-4000-8000-000000000010'),'[]'::jsonb,'Private supplier history unavailable to designer');
SELECT throws_ok($$INSERT INTO storage.objects(bucket_id,name) VALUES('design-instructions','ab100000-0000-4000-8000-000000000010/ab100000-0000-4000-8000-000000000023/ab100000-0000-4000-8000-000000000025.pdf')$$,'42501',NULL,'Designer cannot upload supplier instructions');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='design-instructions'),0::bigint,'Other designer cannot read attachment metadata');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
UPDATE public.orders SET designer_id='ab100000-0000-4000-8000-000000000003' WHERE id='ab100000-0000-4000-8000-000000000012';
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030')$$,'42501','Design access denied','Previous designer loses technical history access');
SELECT ok(NOT public.can_read_design_instruction_file('ab100000-0000-4000-8000-000000000010/ab100000-0000-4000-8000-000000000023/ab100000-0000-4000-8000-000000000024.pdf'),'Previous designer loses attachment access');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000003',true);
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030')->>'paragraph','Safe paragraph','Replacement designer inherits needed technical snapshot');
SELECT * FROM finish();
ROLLBACK;
